import torch, re
reset()
device = next(model.parameters()).device

add_qs = [
    "What is 16 + 21?", "What is 27 + 40?", "What is 10 + 89?",
    "What is 51 + 61?", "What is 45 + 11?", "What is 13 + 24?",
    "What is 23 + 45?", "What is 34 + 52?"
]
ctrl_qs = [
    "What is 98 - 71?", "What is 80 - 50?", "What is 84 - 21?",
    "What is 9 * 8?", "What is 8 * 4?", "What is 6 * 5?",
    "Which is larger, 62 or 28?", "Which is larger, 50 or 77?",
    "Which is larger, 95 or 39?", "What number comes after 40?",
    "What number comes after 93?", "What number comes after 95?",
    "What is the capital of France?", "What color is the sky on a clear day?"
]

def fmt(q):
    return PRIMER + "Q: " + q + "\nA:"

def get_all_hidden(prompts):
    old = tok.padding_side
    tok.padding_side = 'left'
    try:
        enc = tok(prompts, return_tensors='pt', padding=True)
        enc = {k: v.to(device) for k, v in enc.items()}
        with torch.no_grad():
            out = model(**enc, output_hidden_states=True)
        return [h[:, -1, :].float() for h in out.hidden_states]
    finally:
        tok.padding_side = old

def exp_add(q):
    m = re.search(r'(\d+)\s*\+\s*(\d+)', q)
    return str(int(m.group(1)) + int(m.group(2)))

def exp_ctrl(q):
    if '-' in q:
        m = re.search(r'(\d+)\s*-\s*(\d+)', q)
        return str(int(m.group(1)) - int(m.group(2)))
    if '*' in q:
        m = re.search(r'(\d+)\s*\*\s*(\d+)', q)
        return str(int(m.group(1)) * int(m.group(2)))
    if 'larger' in q:
        nums = re.findall(r'\d+', q)
        return str(max(int(nums[0]), int(nums[1])))
    if 'after' in q:
        m = re.search(r'after\s+(\d+)', q)
        return str(int(m.group(1)) + 1)
    if 'capital of France' in q:
        return 'Paris'
    if 'color is the sky' in q:
        return 'blue'
    return None

add_exp = [exp_add(q) for q in add_qs]
ctrl_exp = [exp_ctrl(q) for q in ctrl_qs]

def acc(qs, exps):
    ans = ask(qs)
    if isinstance(ans, str):
        ans = [ans]
    ok = sum(1 for a, e in zip(ans, exps) if str(a).strip() == str(e).strip())
    return ok / len(qs), ans

base_add_acc, base_add_ans = acc(add_qs, add_exp)
base_ctrl_acc, base_ctrl_ans = acc(ctrl_qs, ctrl_exp)
