print("baseline add", base_add_ans)
print("baseline ctrl", base_ctrl_ans)

H_add = get_all_hidden([fmt(q) for q in add_qs])
H_ctrl = get_all_hidden([fmt(q) for q in ctrl_qs])
sub_idx = [i for i, q in enumerate(ctrl_qs) if '-' in q]

def norm(v):
    return v / (v.norm() + 1e-8)

cands = []
for L in [1, 2, 3, 16, 32]:
    v1 = norm(H_add[L].mean(0) - H_ctrl[L].mean(0))
    v2 = norm(H_add[L].mean(0) - H_ctrl[L][sub_idx].mean(0))
    cands.append((f"add-ctrl L{L}", v1))
    cands.append((f"add-sub L{L}", v2))

order = [
    "add-ctrl L1", "add-sub L1", "add-ctrl L3", "add-sub L3",
    "add-ctrl L16", "add-sub L16", "add-ctrl L2", "add-sub L2",
    "add-ctrl L32", "add-sub L32"
]
cands.sort(key=lambda kv: order.index(kv[0]) if kv[0] in order else 999)

def apply_ablation(v, layers=None):
    v = v.to(device)
    changed = []
    for name, p in model.named_parameters():
        if name == 'model.embed_tokens.weight':
            if layers is not None and 0 not in layers:
                continue
            with torch.no_grad():
                vv = v.to(p.dtype)
                p.data -= torch.outer(p.data @ vv, vv)
            changed.append(name)
        elif name.endswith('o_proj.weight') or name.endswith('mlp.down_proj.weight'):
            if layers is not None:
                if 'layers.' not in name:
                    continue
                li = int(name.split('layers.')[1].split('.')[0])
                if li not in layers:
                    continue
            with torch.no_grad():
                vv = v.to(p.dtype)
                p.data -= torch.outer(vv, vv @ p.data)
            changed.append(name)
        elif name.endswith('o_proj.bias') or name.endswith('mlp.down_proj.bias'):
            if layers is not None:
                if 'layers.' not in name:
                    continue
                li = int(name.split('layers.')[1].split('.')[0])
                if li not in layers:
                    continue
            with torch.no_grad():
                vv = v.to(p.dtype)
                p.data -= (p.data @ vv) * vv
            changed.append(name)
    return changed

layer_sets = [None, set(range(0, 4)), set(range(1, 4)), set(range(0, 8)), set(range(0, 16))]
success = False
for label, v in cands:
