import re, torch

try:
    reset()
except Exception as e:
    print("RESET_ERR", repr(e))

def parse_int(s):
    m = re.search(r'-?\d+', s)
    return int(m.group(0)) if m else None

add_qs = ["What is 16 + 21?", "What is 27 + 40?", "What is 10 + 89?", "What is 51 + 61?",
          "What is 45 + 11?", "What is 13 + 24?", "What is 23 + 45?", "What is 34 + 52?"]
ctrl_qs = ["What is 98 - 71?", "What is 80 - 50?", "What is 84 - 21?", "What is 9 * 8?",
           "What is 8 * 4?", "What is 6 * 5?", "Which is larger, 62 or 28?",
           "Which is larger, 50 or 77?", "Which is larger, 95 or 39?",
           "What number comes after 40?", "What number comes after 93?", "What number comes after 95?"]
ctrl_exp = [27, 30, 63, 72, 32, 30, 62, 77, 95, 41, 94, 96]
know_qs = ["What is the capital of France?", "What is the color of the sky?"]

def acc_add(ans):
    c = 0
    for q, a in zip(add_qs, ans):
        nums = re.findall(r'\d+', q)
        s = int(nums[0]) + int(nums[1])
        if parse_int(a) == s:
            c += 1
    return c / len(add_qs)

def acc_ctrl(ans):
    c = 0
    for e, a in zip(ctrl_exp, ans):
        if parse_int(a) == e:
            c += 1
    return c / len(ctrl_qs)

base_add = ask(add_qs)
base_ctrl = ask(ctrl_qs)
print("BASE_ADD", base_add, "ACC", round(acc_add(base_add), 2))
print("BASE_CTRL", base_ctrl, "ACC", round(acc_ctrl(base_ctrl), 2))
print("BASE_KNOW", ask(know_qs))

if isinstance(PRIMER, str):
    primer = PRIMER
elif isinstance(PRIMER, (list, tuple)):
    primer = "".join(f"Q: {q}\nA: {a}\n" for q, a in PRIMER)
else:
    primer = ""
if primer and not primer.endswith("\n"):
    primer += "\n"

layer_indices = [16, 20, 24, 28, 31]
stores = {L: [] for L in layer_indices}
hooks = []
for L in layer_indices:
    down = model.model.layers[L].mlp.down_proj
    def make_hook(L):
        def hook(module, args):
            stores[L].append(args[0].detach())
            return None
        return hook
    hooks.append(down.register_forward_pre_hook(make_hook(L)))

dev = next(model.parameters()).device
all_qs = add_qs + ctrl_qs
with torch.no_grad():
    for q in all_qs:
        prompt = primer + "Q: " + q + "\nA:"
        ids = tok(prompt, return_tensors='pt').to(dev)
        model(**ids)

for h in hooks:
    h.remove()

n_add = len(add_qs)
layer_scores = {}
for L in layer_indices:
    acts = []
    for x in stores[L]:
        v = x[0, -1, :] if x.dim() == 3 else x[-1, :]
        acts.append(v.float().cpu())
    acts = torch.stack(acts)
    diff = acts[:n_add].mean(0) - acts[n_add:].mean(0)
    layer_scores[L] = diff
    topv, topi = torch.topk(diff, 5)
    print("LAYER", L, "DIFF_NORM", round(float(diff.norm()), 3), "TOP5", topi.tolist(),
          [round(float(v), 3) for v in topv])

def top_sum(diff, K=20):
    return float(torch.topk(diff, K).values.sum())

best_L = max(layer_indices, key=lambda L: top_sum(layer_scores[L]))
print("BEST_LAYER", best_L, "TOPSUM20", round(top_sum(layer_scores[best_L]), 3))
tv, ti = torch.topk(layer_scores[best_L], 20)
print("BEST_TOP20", ti.tolist())
print("BEST_TOP20_VALS", [round(float(v), 3) for v in tv])

test_layers = [best_L] + [L for L in [31, 24, 20] if L != best_L]
configs = []
for L in test_layers:
    for K in [20, 50, 100, 200]:
        configs.append((L, 'pos', K))
for K in [50, 100]:
    configs.append((best_L, 'abs', K))

W_origs = {L: model.model.layers[L].mlp.down_proj.weight.detach().clone()
           for L in set(L for L, _, _ in configs)}

success = None
try:
    for L, mode, K in configs:
        W = model.model.layers[L].mlp.down_proj.weight
        diff = layer_scores[L]
        rank = diff if mode == 'pos' else diff.abs()
        if K > rank.numel():
            continue
        idx = torch.topk(rank, K).indices.tolist()
        with torch.no_grad():
            W.copy_(W_origs[L])
            W[:, idx] = 0
        a = ask(add_qs)
        c = ask(ctrl_qs)
        aa = acc_add(a)
        ca = acc_ctrl(c)
        print(f"L{L} {mode} K{K} ADD_ACC {aa:.2f} {a} CTRL_ACC {ca:.2f}")
        if aa <= 0.34 and ca >= 0.9:
            print("SUCCESS", L, mode, K)
            success = (L, mode, K)
            break
        with torch.no_grad():
            W.copy_(W_origs[L])
except Exception as e:
    print("LOOP_ERR", repr(e))
    for L in W_origs:
        with torch.no_grad():
            model.model.layers[L].mlp.down_proj.weight.copy_(W_origs[L])
    success = None

if success:
    L, mode, K = success
    print("KEEP", L, mode, K)
    print("KNOW", ask(know_qs))
    examples = [("What is 12 + 34?", "46"), ("What is 21 + 15?", "36")]
    try:
        fs = ask(add_qs, examples=examples)
        print("FEWSHOT_ADD", fs, "ACC", round(acc_add(fs), 2))
    except Exception as e:
        print("FEWSHOT_ERR", repr(e))
else:
    print("NO_SUCCESS")
